176	Token Lexer::scanRegex(int tline, int tcol) {
177	    std::string v = "/";
178	    bool inClass = false;
179	    while (!atEnd()) {
180	        char ch = peek();
181	        if (ch == '\\') { v += advance(); if (!atEnd()) v += advance(); continue; }
182	        if (ch == '[')  { inClass = true;  v += advance(); continue; }
183	        if (ch == ']')  { inClass = false; v += advance(); continue; }
184	        if (ch == '/' && !inClass) { v += advance(); break; }
185	        v += advance();
186	    }
187	    // flags
188	    while (!atEnd() && std::isalpha(static_cast<unsigned char>(peek())))
189	        v += advance();
190	    return makeToken(TokenKind::Regex, v, tline, tcol);
