#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "diagnostics.h"

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

static void printUsage(const char* argv0) {
    std::cerr << "Usage: " << argv0 << " [options] <input.jsx>\n"
              << "Options:\n"
              << "  -o <file>    Write output to file (default: stdout)\n"
              << "  -h           Show this help\n";
}

static std::string readFile(const std::string& path) {
    std::ifstream f(path);
    if (!f) {
        std::cerr << "error: cannot open '" << path << "'\n";
        std::exit(1);
    }
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

int main(int argc, char** argv) {
    std::string inputPath;
    std::string outputPath;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "--help") {
            printUsage(argv[0]);
            return 0;
        } else if (arg == "-o") {
            if (++i >= argc) { std::cerr << "error: -o requires a filename\n"; return 1; }
            outputPath = argv[i];
        } else if (arg[0] == '-') {
            std::cerr << "error: unknown option '" << arg << "'\n";
            printUsage(argv[0]);
            return 1;
        } else {
            if (!inputPath.empty()) {
                std::cerr << "error: multiple input files not supported\n";
                return 1;
            }
            inputPath = arg;
        }
    }

    if (inputPath.empty()) {
        printUsage(argv[0]);
        return 1;
    }

    std::string source = readFile(inputPath);

    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();

        Parser parser(std::move(tokens));
        auto ast = parser.parse();

        CodeGen gen;
        std::string output = gen.generate(*ast);

        if (outputPath.empty()) {
            std::cout << output;
        } else {
            std::ofstream out(outputPath);
            if (!out) {
                std::cerr << "error: cannot write to '" << outputPath << "'\n";
                return 1;
            }
            out << output;
        }

    } catch (const LexError& e) {
        std::cerr << formatDiag("lex error", e.what(), e.line, e.col) << "\n";
        return 1;
    } catch (const ParseError& e) {
        std::cerr << formatDiag("parse error", e.what(), e.line, e.col) << "\n";
        return 1;
    } catch (const CodeGenError& e) {
        std::cerr << "codegen error: " << e.what() << "\n";
        return 1;
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << "\n";
        return 1;
    }

    return 0;
}

#pragma once
#include <memory>
#include <string>
#include <vector>
#include <variant>

// ---------------------------------------------------------------------------
// Forward declarations
// ---------------------------------------------------------------------------
struct Node;
using NodePtr  = std::unique_ptr<Node>;
using NodeList = std::vector<NodePtr>;

// ---------------------------------------------------------------------------
// Node kinds
// ---------------------------------------------------------------------------
enum class NodeKind {
    // --- Statements ---
    Program,
    ImportDecl,
    ExportDefaultDecl,
    ExportNamedDecl,
    FunctionDecl,
    ArrowFunctionExpr,
    BlockStmt,
    ReturnStmt,
    ExprStmt,
    IfStmt,
    ForStmt,
    WhileStmt,
    VarDecl,        // const/let/var x = ...
    VarDeclarator,

    // --- Expressions ---
    Identifier,
    NumericLiteral,
    StringLiteral,
    TemplateLiteral,
    BoolLiteral,
    NullLiteral,
    BinaryExpr,
    UnaryExpr,
    LogicalExpr,
    AssignExpr,
    CallExpr,
    MemberExpr,
    NewExpr,
    ConditionalExpr,
    SpreadElement,
    ArrayExpr,
    ObjectExpr,
    ObjectProperty,
    SequenceExpr,

    // --- JSX ---
    JSXElement,
    JSXFragment,
    JSXOpeningElement,
    JSXClosingElement,
    JSXSelfClosingElement,
    JSXAttribute,
    JSXSpreadAttribute,
    JSXExpressionContainer,
    JSXText,
    JSXIdentifier,
    JSXMemberExpr,   // Foo.Bar in <Foo.Bar />
};

// ---------------------------------------------------------------------------
// Base node — all concrete data hangs off Node via the 'as' union/variant
// ---------------------------------------------------------------------------
struct Node {
    NodeKind kind;
    int      line = 0;
    int      col  = 0;

    // Children / payload — kept flat to avoid deep inheritance hierarchies.
    // Named fields used by code-gen; unused fields are default-initialised.

    std::string        name;          // identifiers, tag names, operators
    std::string        value;         // literals
    bool               boolVal = false;

    NodeList           children;      // generic child list
    NodeList           params;        // function params
    NodeList           body;          // block body
    NodePtr            init;          // var declarator init / for-init
    NodePtr            test;          // if/for/while condition
    NodePtr            update;        // for-update
    NodePtr            consequent;
    NodePtr            alternate;
    NodePtr            callee;        // CallExpr
    NodeList           arguments;     // CallExpr args
    NodePtr            object;        // MemberExpr object / JSXMemberExpr
    NodePtr            property;      // MemberExpr property
    bool               computed = false;
    NodeList           declarations;  // VarDecl
    NodePtr            declaration;   // ExportDefaultDecl
    NodeList           specifiers;    // ImportDecl named imports
    std::string        source;        // ImportDecl module path
    NodeList           attributes;    // JSXElement attributes
    NodePtr            openingElement;
    NodePtr            closingElement;
    bool               selfClosing = false;
    NodePtr            expression;    // JSXExpressionContainer / ExprStmt
    std::string        varKind;       // "const" | "let" | "var"
    bool               async_ = false;
    NodeList           quasis;        // TemplateLiteral cooked strings
    NodeList           exprs;         // TemplateLiteral expressions
};

// ---------------------------------------------------------------------------
// Factory helpers
// ---------------------------------------------------------------------------
inline NodePtr makeNode(NodeKind k, int line = 0, int col = 0) {
    auto n   = std::make_unique<Node>();
    n->kind  = k;
    n->line  = line;
    n->col   = col;
    return n;
}

