#pragma once
#include "token.h"
#include <string>
#include <vector>

// ---------------------------------------------------------------------------
// LexMode — tells the lexer what context it is currently scanning
// ---------------------------------------------------------------------------
enum class LexMode {
    JS,           // normal JavaScript tokenisation
    JSXTag,       // inside <Tag ... > or </Tag>
    JSXChildren,  // between > ... < (raw JSX text / expression containers)
};

class Lexer {
public:
    explicit Lexer(std::string source);

    // Tokenise the entire source eagerly; the parser works off the vector.
    std::vector<Token> tokenize();

    // The parser pushes/pops modes as it recognises JSX structure.
    void pushMode(LexMode m);
    void popMode();

private:
    std::string          src_;
    size_t               pos_      = 0;
    int                  line_     = 1;
    int                  col_      = 1;
    TokenKind            lastKind_ = TokenKind::EndOfFile;
    std::vector<LexMode> modeStack_;

    LexMode currentMode() const;

    // Character helpers
    char peek(int offset = 0) const;
    char advance();
    bool atEnd() const;
    void skipWhitespaceAndComments();

    // JS token scanners
    Token scanNumber();
    Token scanString(char quote);
    Token scanTemplate();
    Token scanIdentifierOrKeyword();
    Token scanRegex(int tline, int tcol);
    Token scanPunctuation();

    // JSX token scanners
    Token scanJSXText();
    Token scanJSXString(char quote);

    // Disambiguation helpers
    bool regexAllowed() const;
    bool jsxAllowed()   const;

    static TokenKind keywordKind(const std::string& w);
    Token makeToken(TokenKind k, std::string v, int l, int c) const;
};

