41	void Lexer::skipWhitespaceAndComments() {
42	    while (!atEnd()) {
43	        char c = peek();
44	        if (std::isspace(static_cast<unsigned char>(c))) {
45	            advance();
46	        } else if (c == '/' && peek(1) == '/') {
47	            while (!atEnd() && peek() != '\n') advance();
48	        } else if (c == '/' && peek(1) == '*') {
49	            advance(); advance(); // consume /*
50	            while (!atEnd() && !(peek() == '*' && peek(1) == '/'))
51	                advance();
52	            if (!atEnd()) { advance(); advance(); } // consume */
53	        } else {
54	            break;
55	        }
56	    }
57	}
