132	Token Lexer::scanString(char quote) {
133	    int l = line_, c = col_;
134	    advance(); // opening quote
135	    std::string v;
136	    while (!atEnd() && peek() != quote) {
137	        if (peek() == '\\') { v += advance(); if (!atEnd()) v += advance(); }
138	        else                   v += advance();
139	    }
140	    if (atEnd()) throw LexError("Unterminated string literal", l, c);
141	    advance(); // closing quote
142	    return makeToken(TokenKind::String, v, l, c);
143	}
144	
145	Token Lexer::scanTemplate() {
146	    int l = line_, c = col_;
147	    advance(); // `
148	    std::string v;
149	    int depth = 0;
150	    while (!atEnd()) {
151	        char ch = peek();
152	        if (ch == '\\') { v += advance(); if (!atEnd()) v += advance(); }
153	        else if (ch == '$' && peek(1) == '{') {
154	            v += advance(); v += advance(); ++depth;
155	        } else if (ch == '}' && depth > 0) {
156	            v += advance(); --depth;
157	        } else if (ch == '`' && depth == 0) {
158	            advance(); break;
159	        } else {
160	            v += advance();
161	        }
162	    }
163	    return makeToken(TokenKind::TemplateString, v, l, c);
164	}
165	
166	Token Lexer::scanIdentifierOrKeyword() {
167	    int l = line_, c = col_;
168	    std::string v;
169	    while (!atEnd() && (std::isalnum(static_cast<unsigned char>(peek()))
170	                        || peek() == '_' || peek() == '$'))
171	        v += advance();
172	    TokenKind k = keywordKind(v);
173	    return makeToken(k, v, l, c);
174	}
175	
176	Token Lexer::scanRegex(int tline, int tcol) {
177	    std::string v = "/";
178	    bool inClass = false;
179	    while (!atEnd()) {
180	        char ch = peek();
181	        if (ch == '\\') { v += advance(); if (!atEnd()) v += advance(); continue; }
182	        if (ch == '[')  { inClass = true;  v += advance(); continue; }
183	        if (ch == ']')  { inClass = false; v += advance(); continue; }
184	        if (ch == '/' && !inClass) { v += advance(); break; }
185	        v += advance();
186	    }
187	    // flags
188	    while (!atEnd() && std::isalpha(static_cast<unsigned char>(peek())))
189	        v += advance();
190	    return makeToken(TokenKind::Regex, v, tline, tcol);
191	}
