224	        case TokenKind::LBrace:
225	        case TokenKind::Colon:        // ternary :
226	        case TokenKind::QuestionMark: // ternary ?
227	        case TokenKind::PipePipe:
228	        case TokenKind::AmpAmp:
229	        case TokenKind::Arrow:
230	        case TokenKind::QuestionQuestion:
231	        case TokenKind::EndOfFile:
232	            return true;
233	        default:
234	            return false;
