241	Token Lexer::scanJSXText() {
242	    int l = line_, c = col_;
243	    std::string v;
244	    while (!atEnd() && peek() != '<' && peek() != '{')
245	        v += advance();
246	    return makeToken(TokenKind::JSXText, v, l, c);
