249	Token Lexer::scanJSXString(char quote) {
250	    int l = line_, c = col_;
251	    advance(); // opening quote
252	    std::string v;
253	    while (!atEnd() && peek() != quote) {
254	        if (peek() == '\\') { v += advance(); if (!atEnd()) v += advance(); }
255	        else                   v += advance();
256	    }
257	    if (atEnd()) throw LexError("Unterminated JSX attribute string", l, c);
258	    advance();
259	    return makeToken(TokenKind::JSXString, v, l, c);
