263	// Punctuation scanner (JS mode)
264	// ---------------------------------------------------------------------------
265	Token Lexer::scanPunctuation() {
266	    int l = line_, c = col_;
267	    char ch = advance();
268	
269	    auto make = [&](TokenKind k, std::string v) {
270	        return makeToken(k, std::move(v), l, c);
271	    };
272	
273	    switch (ch) {
274	        case '(': return make(TokenKind::LParen,     "(");
275	        case ')': return make(TokenKind::RParen,     ")");
276	        case '{': return make(TokenKind::LBrace,     "{");
277	        case '}': return make(TokenKind::RBrace,     "}");
278	        case '[': return make(TokenKind::LBracket,   "[");
279	        case ']': return make(TokenKind::RBracket,   "]");
280	        case ';': return make(TokenKind::Semicolon,  ";");
281	        case ':': return make(TokenKind::Colon,      ":");
282	        case ',': return make(TokenKind::Comma,      ",");
283	        case '~': return make(TokenKind::Tilde,      "~");
284	        case '^': return make(TokenKind::Caret,      "^");
285	        case '%': {
286	            if (peek() == '=') { advance(); return make(TokenKind::PercentEquals, "%="); }
287	            return make(TokenKind::Percent, "%");
288	        }
289	        case '?': {
290	            if (peek() == '?') { advance(); return make(TokenKind::QuestionQuestion, "??"); }
291	            return make(TokenKind::QuestionMark, "?");
292	        }
293	        case '.': {
294	            if (peek() == '.' && peek(1) == '.') {
295	                advance(); advance(); return make(TokenKind::DotDotDot, "...");
296	            }
297	            return make(TokenKind::Dot, ".");
298	        }
299	        case '=': {
300	            if (peek() == '>') { advance(); return make(TokenKind::Arrow, "=>"); }
301	            if (peek() == '=') {
302	                advance();
303	                if (peek() == '=') { advance(); return make(TokenKind::EqualsEqualsEquals, "==="); }
304	                return make(TokenKind::EqualsEquals, "==");
305	            }
306	            return make(TokenKind::Equals, "=");
307	        }
308	        case '!': {
309	            if (peek() == '=') {
310	                advance();
311	                if (peek() == '=') { advance(); return make(TokenKind::BangEqualsEquals, "!=="); }
312	                return make(TokenKind::BangEquals, "!=");
313	            }
314	            return make(TokenKind::Bang, "!");
315	        }
316	        case '<': {
317	            if (jsxAllowed()) return make(TokenKind::JSXLess, "<");
318	            if (peek() == '<') { advance(); return make(TokenKind::LShift, "<<"); }
319	            if (peek() == '=') { advance(); return make(TokenKind::LessEquals, "<="); }
320	            return make(TokenKind::Less, "<");
321	        }
322	        case '>': {
323	            if (peek() == '>') {
324	                advance();
325	                if (peek() == '>') { advance(); return make(TokenKind::URShift, ">>>"); }
326	                return make(TokenKind::RShift, ">>");
327	            }
328	            if (peek() == '=') { advance(); return make(TokenKind::GreaterEquals, ">="); }
329	            return make(TokenKind::Greater, ">");
330	        }
331	        case '+': {
332	            if (peek() == '+') { advance(); return make(TokenKind::PlusPlus, "++"); }
333	            if (peek() == '=') { advance(); return make(TokenKind::PlusEquals, "+="); }
334	            return make(TokenKind::Plus, "+");
335	        }
336	        case '-': {
337	            if (peek() == '-') { advance(); return make(TokenKind::MinusMinus, "--"); }
338	            if (peek() == '=') { advance(); return make(TokenKind::MinusEquals, "-="); }
339	            return make(TokenKind::Minus, "-");
340	        }
341	        case '*': {
342	            if (peek() == '=') { advance(); return make(TokenKind::StarEquals, "*="); }
343	            return make(TokenKind::Star, "*");
344	        }
345	        case '/': {
346	            if (regexAllowed()) return scanRegex(l, c);
347	            if (peek() == '=') { advance(); return make(TokenKind::SlashEquals, "/="); }
348	            return make(TokenKind::Slash, "/");
349	        }
350	        case '&': {
351	            if (peek() == '&') { advance(); return make(TokenKind::AmpAmp, "&&"); }
352	            return make(TokenKind::Amp, "&");
353	        }
354	        case '|': {
355	            if (peek() == '|') { advance(); return make(TokenKind::PipePipe, "||"); }
356	            return make(TokenKind::Pipe, "|");
357	        }
358	        default:
359	            return make(TokenKind::Unknown, std::string(1, ch));
360	    }
361	}
