363	// ---------------------------------------------------------------------------
364	// Main tokenise loop
365	//
366	// The lexer self-manages the JSX mode stack as it emits tokens:
367	//
368	//   JSXLess emitted (JS mode)  -> push JSXTag
369	//   JSXGreater emitted (tag)   -> pop JSXTag, push JSXChildren
370	//   JSXSlashGreater emitted    -> pop JSXTag          (self-closing)
371	//   JSXLessSlash emitted       -> pop JSXChildren, push JSXTag (closing tag)
372	//   JSXGreater emitted (close) -> pop JSXTag          (closing tag done)
373	//   LBrace in JSXChildren      -> push JS
374	//   RBrace in JS, parent=jsx   -> pop JS, back to JSXChildren
375	//
376	// A small "brace depth" counter inside each JS-inside-JSX context lets us
377	// pop back to JSXChildren after the matching }.  We track this with a
378	// parallel stack of brace depths.
379	// ---------------------------------------------------------------------------
380	std::vector<Token> Lexer::tokenize() {
381	    std::vector<Token> tokens;
382	
383	    // Each entry on jsxBraceDepth corresponds to one JS-inside-JSX expression.
384	    // When we push JS mode from JSXChildren we record the current JS brace
385	    // depth; when it returns to that depth and we see } we pop back.
386	    std::vector<int> jsxBraceDepth;
387	    int  braceDepth   = 0;    // tracks { } in JS mode
388	    bool inClosingTag = false; // true after JSXLessSlash, cleared after JSXGreater
389	
390	    while (true) {
391	        // In JSXChildren we do NOT skip whitespace — it may be JSXText.
392	        if (currentMode() != LexMode::JSXChildren)
393	            skipWhitespaceAndComments();
394	
395	        if (atEnd()) {
396	            tokens.push_back(makeToken(TokenKind::EndOfFile, "", line_, col_));
397	            break;
398	        }
399	
400	        LexMode mode = currentMode();
401	        Token   tok;
402	
403	        // ----------------------------------------------------------------
404	        // JSXChildren mode: raw text, { expr }, or nested < tag
405	        // ----------------------------------------------------------------
406	        if (mode == LexMode::JSXChildren) {
407	            char ch = peek();
408	
409	            if (ch == '<') {
410	                int l = line_, c = col_;
411	                advance();
412	                if (peek() == '/') {
413	                    advance();
414	                    tok = makeToken(TokenKind::JSXLessSlash, "</", l, c);
415	                    inClosingTag = true;
416	                    // closing tag: swap children -> tag
417	                    popMode();
418	                    pushMode(LexMode::JSXTag);
419	                } else {
420	                    tok = makeToken(TokenKind::JSXLess, "<", l, c);
421	                    // nested opening tag
422	                    pushMode(LexMode::JSXTag);
423	                }
424	            } else if (ch == '{') {
425	                int l = line_, c = col_;
426	                advance();
427	                tok = makeToken(TokenKind::LBrace, "{", l, c);
428	                // Enter JS expression inside JSX; remember brace depth to pop back
429	                jsxBraceDepth.push_back(braceDepth);
430	                pushMode(LexMode::JS);
431	            } else {
432	                // Skip leading whitespace manually so we can still detect empty text
433	                tok = scanJSXText();
434	                // Suppress pure-whitespace JSXText tokens — parser already
435	                // filters them, but emitting them cleans up the stream too.
436	                if (tok.value.empty()) continue;
437	            }
438	
439	        // ----------------------------------------------------------------
440	        // JSXTag mode: tag name, attributes, /> or >
441	        // ----------------------------------------------------------------
442	        } else if (mode == LexMode::JSXTag) {
443	            skipWhitespaceAndComments();
444	            char ch = peek();
445	
446	            if (ch == '/' && peek(1) == '>') {
447	                int l = line_, c = col_;
448	                advance(); advance();
449	                tok = makeToken(TokenKind::JSXSlashGreater, "/>", l, c);
450	                popMode(); // back to wherever we came from (JS or JSXChildren)
451	            } else if (ch == '>') {
452	                int l = line_, c = col_;
453	                advance();
454	                tok = makeToken(TokenKind::JSXGreater, ">", l, c);
455	                if (inClosingTag) {
456	                    // closing tag finished: pop JSXTag, back to parent context
457	                    inClosingTag = false;
458	                    popMode();
459	                } else {
460	                    // opening tag: switch JSXTag -> JSXChildren
461	                    popMode();
462	                    pushMode(LexMode::JSXChildren);
463	                }
464	            } else if (ch == '{') {
465	                // spread attribute: {...x}
466	                int l = line_, c = col_;
467	                advance();
468	                tok = makeToken(TokenKind::LBrace, "{", l, c);
469	                jsxBraceDepth.push_back(braceDepth);
470	                pushMode(LexMode::JS);
471	            } else if (ch == '"' || ch == '\'') {
472	                tok = scanJSXString(ch);
473	            } else if (ch == '.' && peek(1) == '.' && peek(2) == '.') {
474	                int l = line_, c = col_;
475	                advance(); advance(); advance();
476	                tok = makeToken(TokenKind::DotDotDot, "...", l, c);
477	            } else if (ch == '.') {
478	                int l = line_, c = col_;
479	                advance();
480	                tok = makeToken(TokenKind::Dot, ".", l, c);
481	            } else if (ch == '=') {
482	                int l = line_, c = col_;
483	                advance();
484	                tok = makeToken(TokenKind::Equals, "=", l, c);
485	            } else if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_') {
486	                tok = scanIdentifierOrKeyword();
487	                tok.kind = TokenKind::Identifier; // keywords are just names in JSX tags
488	            } else {
489	                tok = makeToken(TokenKind::Unknown, std::string(1, advance()), line_, col_);
490	            }
491	
492	        // ----------------------------------------------------------------
493	        // JS mode (default)
494	        // ----------------------------------------------------------------
495	        } else {
496	            char ch = peek();
497	
498	            // Track brace depth so we know when a JS-inside-JSX expr ends.
499	            // jsxBraceDepth stores the braceDepth at the time we entered JS
500	            // from a JSX context.  The matching } is the one that brings us
501	            // back to that same depth (before decrement).
502	            if (ch == '}' && !jsxBraceDepth.empty() && braceDepth == jsxBraceDepth.back()) {
503	                // This } closes the JSX expression container.
504	                int l = line_, c = col_;
505	                advance();
506	                tok = makeToken(TokenKind::RBrace, "}", l, c);
507	                jsxBraceDepth.pop_back();
508	                popMode(); // back to JSXChildren or JSXTag
509	                lastKind_ = tok.kind;
510	                tokens.push_back(std::move(tok));
511	                continue;
512	            }
513	            if (ch == '{') ++braceDepth;
514	            else if (ch == '}') --braceDepth;
515	
516	            if (std::isdigit(static_cast<unsigned char>(ch))) {
517	                tok = scanNumber();
518	            } else if (ch == '"' || ch == '\'') {
519	                tok = scanString(ch);
520	            } else if (ch == '`') {
521	                tok = scanTemplate();
522	            } else if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_' || ch == '$') {
523	                tok = scanIdentifierOrKeyword();
524	            } else {
525	                tok = scanPunctuation();
526	            }
527	        }
528	
529	        lastKind_ = tok.kind;
530	
531	        // After emitting JSXLess in JS mode, enter JSXTag so the next
532	        // iteration scans tag name / attributes correctly.
533	        if (tok.kind == TokenKind::JSXLess && currentMode() == LexMode::JS)
534	            pushMode(LexMode::JSXTag);
535	
536	        tokens.push_back(std::move(tok));
537	    }
538	
539	    return tokens;
540	}
