86	NodePtr Parser::parseImportDecl() {
87	    const Token& start = expect(TokenKind::KW_import, "import");
88	    auto n = makeNode(NodeKind::ImportDecl, start.line, start.col);
89	
90	    if (check(TokenKind::String)) {
91	        // import "side-effect"
92	        n->source = advance().value;
93	    } else if (check(TokenKind::LBrace)) {
94	        // import { X, Y } from "mod"
95	        advance();
96	        while (!check(TokenKind::RBrace) && !atEnd()) {
97	            auto spec = makeNode(NodeKind::Identifier, peek().line, peek().col);
98	            spec->name = advance().value;
99	            if (match(TokenKind::KW_as)) {
100	                spec->value = advance().value; // local alias
101	            }
102	            n->specifiers.push_back(std::move(spec));
103	            if (!match(TokenKind::Comma)) break;
104	        }
105	        expect(TokenKind::RBrace, "}");
106	        expect(TokenKind::KW_from, "from");
107	        n->source = expect(TokenKind::String, "module path").value;
108	    } else if (check(TokenKind::Star)) {
109	        // import * as ns from "mod"
110	        advance();
111	        expect(TokenKind::KW_as, "as");
112	        auto spec = makeNode(NodeKind::Identifier, peek().line, peek().col);
113	        spec->name  = "*";
114	        spec->value = advance().value;
115	        n->specifiers.push_back(std::move(spec));
116	        expect(TokenKind::KW_from, "from");
117	        n->source = expect(TokenKind::String, "module path").value;
118	    } else {
119	        // import Default from "mod"
120	        auto spec = makeNode(NodeKind::Identifier, peek().line, peek().col);
121	        spec->name = advance().value;
122	        n->specifiers.push_back(std::move(spec));
123	        if (match(TokenKind::Comma)) {
124	            // import Default, { Named } from "mod"
125	            expect(TokenKind::LBrace, "{");
126	            while (!check(TokenKind::RBrace) && !atEnd()) {
127	                auto s = makeNode(NodeKind::Identifier, peek().line, peek().col);
128	                s->name = advance().value;
129	                n->specifiers.push_back(std::move(s));
130	                if (!match(TokenKind::Comma)) break;
131	            }
132	            expect(TokenKind::RBrace, "}");
133	        }
134	        expect(TokenKind::KW_from, "from");
135	        n->source = expect(TokenKind::String, "module path").value;
136	    }
137	    match(TokenKind::Semicolon);
138	    return n;
139	}
