275	NodePtr Parser::parseReturnStmt() {
276	    const Token& start = expect(TokenKind::KW_return, "return");
277	    auto n = makeNode(NodeKind::ReturnStmt, start.line, start.col);
278	    if (!check(TokenKind::Semicolon) && !check(TokenKind::RBrace) && !atEnd()) {
279	        inExpressionContext_ = true;
280	        n->expression = parseExpr();
281	        inExpressionContext_ = false;
282	    }
283	    match(TokenKind::Semicolon);
284	    return n;
285	}
286	
287	NodePtr Parser::parseIfStmt() {
288	    const Token& start = expect(TokenKind::KW_if, "if");
289	    auto n = makeNode(NodeKind::IfStmt, start.line, start.col);
290	    expect(TokenKind::LParen, "(");
291	    n->test = parseExpr();
292	    expect(TokenKind::RParen, ")");
293	    n->consequent = parseStatement();
294	    if (match(TokenKind::KW_else)) n->alternate = parseStatement();
295	    return n;
296	}
